<?php
require 'config/database.php'; require 'includes/functions.php';
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT m.*,k.nama AS kategori FROM mobil m LEFT JOIN kategori k ON k.id=m.kategori_id WHERE m.id=?');$stmt->execute([$id]);$car=$stmt->fetch();
if(!$car){http_response_code(404);$page_title='Mobil tidak ditemukan';$active='catalog';include 'includes/header.php';echo '<section class="section container"><div class="empty">Data mobil tidak ditemukan. <a href="catalog.php">Kembali ke katalog</a></div></section>';include 'includes/footer.php';exit;}
$page_title=$car['nama'];$active='catalog';include 'includes/header.php'; ?>
<section class="container detail-grid"><div><img src="<?= e(image_or_placeholder($car['foto'])) ?>" alt="<?= e($car['nama']) ?>" onerror="this.src='assets/img/car-placeholder.svg'"></div><div><span class="eyebrow"><?= e($car['kategori']??'Mobil') ?></span><h1><?= e($car['nama']) ?></h1><div class="price"><?= rupiah($car['harga']) ?></div><span class="badge <?= $car['status']==='Terjual'?'sold':'' ?>"><?= e($car['status']) ?></span><p><?= nl2br(e($car['deskripsi'] ?: 'Informasi kendaraan tersedia sesuai data katalog.')) ?></p><div class="specs"><div class="spec"><small>Tahun</small><strong><?= e($car['tahun']) ?></strong></div><div class="spec"><small>Merek</small><strong><?= e($car['merek']) ?></strong></div><div class="spec"><small>Transmisi</small><strong><?= e($car['transmisi']) ?></strong></div><div class="spec"><small>Bahan bakar</small><strong><?= e($car['bahan_bakar']) ?></strong></div></div><p><a class="btn secondary" href="catalog.php">← Kembali ke katalog</a></p></div></section>
<?php include 'includes/footer.php'; ?>
